python3 - <<'EOF'
import glob,json,os,datetime as dt
now=dt.datetime.now(dt.timezone.utc)
files=glob.glob('bus/inbox/*.jsonl')
def ev(p):
    for ln in open(p,encoding='utf-8'):
        ln=ln.strip()
        if not ln: continue
        try: yield json.loads(ln)
        except: pass
res=[]
for p in files:
    for r in ev(p):
        if r.get('event_type') in ('answer','decision'):
            t=r.get('topic')
            if not t: continue
            try: rts=dt.datetime.fromisoformat(r.get('ts','').replace('Z','+00:00'))
            except: continue
            res.append((t,rts,os.path.basename(p)[:-6]))
for p in sorted(files):
    a=os.path.basename(p)[:-6]
    for r in ev(p):
        if r.get('event_type')!='question': continue
        t=r.get('topic') or ''
        try: qts=dt.datetime.fromisoformat(r.get('ts','').replace('Z','+00:00'))
        except: continue
        m=[(rt,rts,ra) for rt,rts,ra in res if (rt==t or t in rt) and rts>=qts]
        if m:
            rt,rts,ra=sorted(m,key=lambda x:x[1])[0]
            print(f"CLOSED  {a}/{t[:55]!r:60} <= {ra} {rts:%m-%d %H:%M} {rt[:60]!r}")
        else:
            print(f"OPEN    {a}/{t[:55]!r} ({(now-qts).days}d)")
EOF
